// Expected attributes/height/identity are retained original ARM stores, not
// values generated by the native implementation. Overlay controls are native
// transaction/identity boundaries; they do not claim new original executions.
#include "spatial_query.hpp"
#include "picosha2.h"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>
namespace {
namespace sq=mh4u::spatial_query;namespace cr=mh4u::collision_resource;
using W=std::uint32_t;using Bytes=std::vector<std::uint8_t>;
std::size_t checks{};
void check(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}
template<class T,class E>T take(std::variant<T,E> value){if(const auto* e=std::get_if<E>(&value)){
 if constexpr(requires{e->field;})throw std::runtime_error(std::string(e->field));else throw std::runtime_error("Source decode failure");}
 return std::get<T>(std::move(value));}
Bytes read(const char* path){std::ifstream in(path,std::ios::binary|std::ios::ate);if(!in)throw std::runtime_error("Fixture open");const auto n=in.tellg();if(n<0||n>8192)throw std::runtime_error("Fixture extent");Bytes out(static_cast<std::size_t>(n));in.seekg(0);if(!in.read(reinterpret_cast<char*>(out.data()),n)||in.peek()!=std::char_traits<char>::eof())throw std::runtime_error("Fixture read");return out;}
W word(const Bytes& b,std::size_t p){check(p<=b.size()&&b.size()-p>=4,"Fixture word extent");W out=0;for(unsigned i=0;i<4;++i)out|=W(b[p+i])<<(8*i);return out;}
struct Row {std::array<W,20> w;Bytes before,after;};
std::vector<Row> parse(const Bytes& b,std::string_view hash){check(b.size()==5148,"Fixture complete size");check(std::string(b.begin(),b.begin()+8)=="MH4USCA1"&&word(b,8)==29,"Fixture schema/count");
 std::string h;constexpr char hex[]="0123456789abcdef";for(std::size_t i=12;i<44;++i){h+=hex[b[i]>>4];h+=hex[b[i]&15];}check(h==hash,"Fixture resource binding");std::vector<Row> rows;
 for(std::size_t i=0;i<29;++i){const auto p=44+i*176;Row row;for(std::size_t j=0;j<20;++j)row.w[j]=word(b,p+4*j);row.before=Bytes(b.begin()+p+80,b.begin()+p+128);row.after=Bytes(b.begin()+p+128,b.begin()+p+176);check(row.w[4]!=0&&row.w[5]==3&&(row.w[6]==0x40000||row.w[6]==0),"Original request domain");rows.push_back(std::move(row));}return rows;}
sq::Scene scene(const cr::Resource& r){sq::Scene s;for(auto& d:s.direct)d=std::vector<sq::Node>{};for(auto& f:s.other_empty)for(auto& e:f)e=true;for(auto& f:s.extra_c8_empty)for(auto& e:f)e=true;
 s.extra_c8_enabled=true;s.extra_c9_enabled=true;s.extra_c9_empty=true;s.extra_tail_count=0;s.status_selector_a=0;s.status_selector_b=0;s.normal_thresholds={0xc0000000,0xc0000000,0xc0000000};s.classification_masks={0x02000000,0,0};
 sq::Instance x;x.enabled_5=1;x.bypass_pair_box_33=0;x.object_mask=1;x.area_mask=8;x.exclusion_tag=0;x.resource_present=true;x.tree_present=false;x.grid_present=true;x.resource=r;x.status_count=1;x.grid_state=0;x.status={1,0,0,false,false};s.instances.push_back(x);
 s.grid_states.push_back({r,0,0,0,std::vector<std::optional<W>>(r.groups()[0].pairs.count,0)});
 s.direct[3]=std::vector<sq::Node>{{0,r.groups()[0].bbox_min[0],r.groups()[0].bbox_max[2]}};return s;}
sq::HeightRequest request(const Row& r){return {sq::Bits3{r.w[1],r.w[2],r.w[3]},true,r.w[4],r.w[5],r.w[6],r.w[7],true};}
void attributes(const sq::DirectAttribute& a,const Row& r,const cr::Resource& resource){
 check(a.resource.sha256()==resource.sha256(),"Attribute keeps source identity");check(a.identity.instance==r.w[14]&&a.identity.group==r.w[15]&&a.identity.pair==r.w[16]&&a.identity.face==r.w[17],"Original hit identity");
 const auto pair=take(resource.resolve_pair(a.identity.group,a.identity.pair));check(pair.attribute->source_offset==r.w[19]&&pair.first.face->source_offset==r.w[18],"Original pointer-to-owner projection");
 check(a.identity.attribute==pair.pair->attribute_id,"Attribute record ID");for(unsigned i=0;i<6;++i)check(a.bytes0_5[i]==r.after[i],"Original output byte");for(unsigned i=0;i<3;++i){check(a.words2_4_0[i]==word(r.after,8+4*i),"Original output word");check(a.normal_bits[i]==word(r.after,24+4*i),"Original raw normal word");}
 check(a.word24==word(r.after,36),"Original output+24");check(!a.opaque28&&!a.opaque2c,"Unwritten words stay Unknown");check(std::equal(r.before.begin()+40,r.before.end(),r.after.begin()+40),"Original opaque lanes unchanged");
}
void corpus(const std::vector<Row>& rows,const cr::Resource& r){for(const auto& row:rows){auto s=scene(r);s.classification_masks={row.w[8],row.w[9],row.w[10]};const auto out=take(sq::height(s,request(row)));if(out.height_bits!=row.w[11]||out.status!=row.w[12]||out.query.classification!=row.w[13])throw std::runtime_error("Original height/status/classification case "+std::to_string(row.w[0])+" got "+std::to_string(out.height_bits)+"/"+std::to_string(out.status)+"/"+std::to_string(out.query.classification)+" expected "+std::to_string(row.w[11])+"/"+std::to_string(row.w[12])+"/"+std::to_string(row.w[13]));check(true,"Original height/status/classification");check(bool(out.attribute),"Requested original attribute returned");attributes(*out.attribute,row,r);check(s.grid_states[0].counter==0,"No publication during query");for(const auto& x:s.grid_states[0].pair_marks)check(x==0,"Source marks untouched");}}
bool same(const sq::GridState& a,const sq::GridState& b){return a.resource.sha256()==b.resource.sha256()&&a.group==b.group&&a.counter==b.counter&&a.depth==b.depth&&a.pair_marks==b.pair_marks;}
void error(const sq::Result<std::vector<sq::GridUpdate>>& result,sq::GridPlanCode code){const auto* e=std::get_if<sq::Error>(&result);check(e&&e->plan&&e->plan->code==code,"Typed grid-plan failure");}
cr::Resource changed(const cr::Resource& r,std::size_t at,W value){std::string b(reinterpret_cast<const char*>(r.bytes().data()),r.bytes().size());for(unsigned i=0;i<4;++i)b.at(at+i)=char(value>>(8*i));return take(cr::Resource::decode(b,picosha2::hash256_hex_string(b)));}
cr::Resource empty_resource(const cr::Resource& r){const auto bytes=r.bytes();const auto g=take(r.grid(0));std::string b;auto append=[&](std::size_t start,std::size_t n){b.append(reinterpret_cast<const char*>(bytes.data()+start),n);};append(0,r.sections()[1].offset);append(r.sections()[2].offset,r.core_end_offset()-r.sections()[2].offset);for(const auto at:{std::size_t(20),std::size_t(r.groups()[0].source_offset+48)})for(unsigned i=0;i<4;++i)b.at(at+i)=0;append(g.source_offset,46);b.append(g.cells.size()*8+4,'\0');check(bool(r.global_tail_offset()),"Empty resource tail known");append(*r.global_tail_offset(),bytes.size()-*r.global_tail_offset());return take(cr::Resource::decode(b,picosha2::hash256_hex_string(b)));}
void controls(const Row& row,const cr::Resource& r){auto s=scene(r);auto req=request(row);auto first=take(sq::height(s,req));check(first.query.grid_updates.size()==1,"First plan slot");auto prior=first.query.grid_updates;check(prior[0].state.counter==1,"First counter");
 auto second=take(sq::height(s,req,{},prior));check(second.query.grid_updates[0].state.counter==2,"Overlay advances prior counter");auto committed=s;committed.grid_states[0]=prior[0].state;auto sequential=take(sq::height(committed,req));check(same(second.query.grid_updates[0].state,sequential.query.grid_updates[0].state),"Overlay equals explicit sequential publication");check(s.grid_states[0].counter==0&&prior[0].state.counter==1,"Both inputs immutable");
 auto alias=s;alias.instances.push_back(alias.instances[0]);alias.direct[3]->push_back({1,r.groups()[0].bbox_min[0],r.groups()[0].bbox_max[2]});auto repeated=take(sq::height(alias,req,{},prior));check(repeated.query.grid_updates.size()==1&&repeated.query.grid_updates[0].state.counter==3,"Distinct instances share canonical grid");check(repeated.query.hit->identity.instance==1,"Equal-distance later instance order preserved");
 auto skip=req;skip.area=32;skip.attribute_output_present.reset();auto missed=take(sq::height(s,skip,{},second.query.grid_updates));check(!missed.query.hit&&!missed.attribute&&same(missed.query.grid_updates[0].state,second.query.grid_updates[0].state),"Untouched earlier patches retained on miss");
 auto unknown=prior;unknown[0].state.counter.reset();check(!take(sq::height(s,skip,{},unknown)).query.grid_updates[0].state.counter,"Unused unknown counter retained");check(std::get<sq::Error>(sq::height(s,req,{},unknown)).field=="grid counter","Reached unknown counter fails");
 auto invalid=prior;invalid[0].slot=1;error(sq::plan_updates(s,invalid),sq::GridPlanCode::invalid_slot);invalid=prior;invalid.push_back(prior[0]);error(sq::plan_updates(s,invalid),sq::GridPlanCode::duplicate_slot);error(sq::plan_updates(s,{},invalid),sq::GridPlanCode::duplicate_slot);
 invalid=prior;invalid[0].state.group=1;error(sq::plan_updates(s,invalid),sq::GridPlanCode::source_binding);invalid=prior;invalid[0].state.pair_marks.pop_back();error(sq::plan_updates(s,invalid),sq::GridPlanCode::source_binding);
 invalid=prior;invalid[0].state.resource=changed(r,0x20,0x12345678);error(sq::plan_updates(s,invalid),sq::GridPlanCode::source_binding);
 auto merged=take(sq::plan_updates(s,prior,second.query.grid_updates));check(merged.size()==1&&same(merged[0].state,second.query.grid_updates[0].state),"Latest state wins exactly once");
 sq::Limits limits;limits.runtime_words=r.groups()[0].pairs.count-1;error(sq::plan_updates(s,prior,{},limits),sq::GridPlanCode::resource_limit);limits={};limits.runtime_slots=0;error(sq::plan_updates(s,prior,{},limits),sq::GridPlanCode::resource_limit);
 auto two=s;two.grid_states.push_back(two.grid_states[0]);auto later=prior;later[0].slot=1;limits={};limits.runtime_slots=1;error(sq::plan_updates(two,prior,later,limits),sq::GridPlanCode::resource_limit);limits={};limits.runtime_words=r.groups()[0].pairs.count;error(sq::plan_updates(two,prior,later,limits),sq::GridPlanCode::resource_limit);auto union_=take(sq::plan_updates(two,later,prior));check(union_.size()==2&&union_[0].slot==0&&union_[1].slot==1,"Plan canonical slot ordering");
 auto zero=scene(empty_resource(r));sq::GridUpdate z{0,zero.grid_states[0]};z.state.counter=7;limits={};limits.runtime_words=0;check(take(sq::plan_updates(zero,std::span(&z,1),{},limits)).size()==1,"Zero pairs still allow one update slot");
 auto null=req;null.attribute_output_present=false;check(!take(sq::height(s,null)).attribute,"Known null output remains absent");null.attribute_output_present.reset();check(std::get<sq::Error>(sq::height(s,null)).field=="height attribute output presence","Hit consumes output presence");auto disabled=s;disabled.instances[0].enabled_5=0;check(!take(sq::height(disabled,null)).attribute,"Miss does not consume output presence");
 for(unsigned i=0;i<3;++i){auto unsupported=s;if(i==0)unsupported.instances[0].status.field20=1;else if(i==1)unsupported.instances[0].status.pointer24_present=true;else unsupported.instances[0].status.pointer30_present=true;check(std::get<sq::Error>(sq::height(unsupported,req)).code==sq::ErrorCode::unsupported_route,"Broader carrier/transform remains unsupported");}
 // Native-only packed-bit boundary, using a distinct source-bound parsed SBC.
 const auto identity=first.query.hit->identity;const auto offset=r.attributes()[identity.attribute].source_offset;
 auto packed=changed(r,offset+4,0xabcdef5a);auto packed_scene=scene(packed);auto packed_out=take(sq::height(packed_scene,req));check(packed_out.attribute->bytes0_5==std::array<std::uint8_t,6>{0x5a,7,1,0xd,0xc,0xab},"Packed word extraction source bits");
 std::string normals(reinterpret_cast<const char*>(r.bytes().data()),r.bytes().size());
 for(const auto& f:r.faces())for(unsigned axis=0;axis<3;++axis){const W v=axis==1?0x40000000U:0x80000000U;for(unsigned byte=0;byte<4;++byte)normals[f.source_offset+4*axis+byte]=char(v>>(8*byte));}
 auto raw_normal=take(cr::Resource::decode(normals,picosha2::hash256_hex_string(normals)));auto raw_scene=scene(raw_normal);auto raw_out=take(sq::height(raw_scene,req));check(raw_out.attribute&&raw_out.attribute->normal_bits==sq::Bits3{0x80000000,0x40000000,0x80000000},"Non-unit source normal and negative zeros preserved");
 auto retained=[&](){auto temp=scene(r);return *take(sq::height(temp,req)).attribute;}();check(retained.resource.sha256()==r.sha256()&&retained.resource.faces().size()==r.faces().size(),"Returned attribute owns source lifetime");
 check(s.grid_states[0].counter==0&&prior[0].state.counter==1,"Failures publish no grid mutation");
}
}
int main(int argc,char** argv){try{if(argc!=5)throw std::runtime_error("Usage: spatial-contact-tests fixture sha256 SBC sha256");auto b=read(argv[1]);check(picosha2::hash256_hex_string(b)==argv[2],"Fixture SHA");auto r=take(cr::Resource::load(argv[3],argv[4]));auto rows=parse(b,r.sha256());corpus(rows,r);controls(rows[0],r);std::cout<<"{\"status\":\"passed\",\"original_calls\":29,\"checks\":"<<checks<<"}\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
